# Proper generator: parse with XmlDocument (ignores comments), verify that the
# vanilla file exists in the SDK SageXml tree, and only then emit the override.
$srcRoot  = (Get-Item 'd:\Games\RA3_modding\MOD*\CnC_Modding_Support\Red Alert 3\Xml').FullName
$sageRoot = 'd:\Games\RA3_modding\RA3_MODSDK-X\SageXml'
$outFile  = 'd:\Games\RA3_modding\yuris-retaliation\src\Retaliation\Data\UnitOverrides\UnitOverrides.xml'
$report   = 'd:\Games\RA3_modding\_gen2_report.txt'

# All three factions. Two filters keep the generated file safe:
#   * only the primary unit (id == file name) and "_xxx" variants, because
#     instantiating a variant forces the builder to resolve its models and the
#     SDK's Art folder does not contain every asset (e.g.
#     SUAntiInfantryInfantry_MMCNC.w3x is missing -> "length must not be
#     negative" + GB2312 decoder errors);
#   * units that already declare their own LUAEventList are skipped entirely
#     (replacing that module kills their OnCreated handler, e.g. the Hammer
#     Tank's salvage-weapon hiding).
$dirs = @('Allied\Units', 'Soviet\Units', 'Japan\Units')
$seen = @{}
$groups = New-Object System.Collections.ArrayList
$rep = New-Object System.Collections.ArrayList

foreach ($d in $dirs) {
    $full = Join-Path $srcRoot $d
    if (-not (Test-Path $full)) { [void]$rep.Add("MISSING SRC $d"); continue }
    foreach ($f in (Get-ChildItem $full -Recurse -Filter *.xml)) {
        $rel = $f.FullName.Substring($srcRoot.Length + 1).Replace('\', '/')
        # the include must resolve inside the SDK's DATA root
        $sdkPath = Join-Path $sageRoot ($rel.Replace('/', '\'))
        if (-not (Test-Path $sdkPath)) { [void]$rep.Add("SKIP (not in SageXml): $rel"); continue }
        try { $doc = New-Object System.Xml.XmlDocument; $doc.Load($f.FullName) }
        catch { [void]$rep.Add("SKIP (xml error): $rel"); continue }
        $nodes = $doc.SelectNodes('//*[local-name()="GameObject"]')
        $base = [IO.Path]::GetFileNameWithoutExtension($f.Name)
        $ids = @()
        foreach ($n in $nodes) {
            if (-not $n.HasAttribute('id')) { continue }
            $id = $n.GetAttribute('id')
            if ($id -like 'Base*') { continue }
            # Only the primary unit (same id as the file) and "_xxx" variants.
            # Reason: instantiating a GameObject forces the builder to resolve
            # its models, and the SDK's Art folder does not contain every asset
            # (e.g. SUAntiInfantryInfantry_MMCNC.w3x is missing, which broke the
            # build for SovietAntiInfantryInfantryMolotovCocktail with
            # "长度不能小于 0 / 参数名: length" + GB2312 decoder fallback errors).
            if ($id -ne $base -and $id -notlike ($base + '_*')) { continue }
            if ($seen.ContainsKey($id)) { continue }
            # CRITICAL: never touch a unit that already declares a LUAEventList.
            # Vanilla units use <LUAEventList id="ModuleTag_LUAEventList"
            # EventListName="<Unit>Functions"/>, and those lists inherit
            # BaseScriptFunctions, so they already receive BecomeDissident.
            # Re-declaring the module replaces it (module identity = id), which
            # kills the unit's own OnCreated handler - e.g. the Hammer Tank's
            # OnSovietAntiVehicleVehicleTech1Created hides every salvage weapon
            # sub-object, so replacing it made ALL secondary weapon models show
            # at once.
            if ($n.SelectNodes('.//*[local-name()="LUAEventList"]').Count -gt 0) {
                [void]$rep.Add("KEEP (already has LUAEventList): $id")
                continue
            }
            $seen[$id] = 1
            $ids += $id
        }
        if ($ids.Count -eq 0) { continue }
        [void]$groups.Add([pscustomobject]@{ Rel = $rel; Ids = $ids })
        [void]$rep.Add("OK $rel -> $($ids.Count)")
    }
}

$sb = New-Object System.Text.StringBuilder
[void]$sb.AppendLine('<?xml version="1.0" encoding="utf-8"?>')
[void]$sb.AppendLine('<AssetDeclaration xmlns="uri:ea.com:eala:asset" xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance">')
[void]$sb.AppendLine('    <!-- GENERATED by scripts/gen-unitoverrides.ps1 - do not edit by hand.')
[void]$sb.AppendLine('')
[void]$sb.AppendLine('         Gives every vanilla combat unit a LUAEventList -> BaseScriptFunctions.')
[void]$sb.AppendLine('         A LUAEventList declared on BaseInfantry/BaseVehicle is NOT inherited by')
[void]$sb.AppendLine('         child objects, so a ScriptedEvent such as BecomeDissident only reached')
[void]$sb.AppendLine('         units that declare the module themselves - previously only the Conscript.')
[void]$sb.AppendLine('         Proof: every [BecomeDissident] line in LIVE_OUTPUT.txt had template')
[void]$sb.AppendLine('         19ab11af = 0x19AB11AF = 430641583 = SovietAntiInfantryInfantry.')
[void]$sb.AppendLine('')
[void]$sb.AppendLine('         Per unit: include the vanilla asset, re-declare it with')
[void]$sb.AppendLine('         inheritFrom="self" and add the single behaviour. Nothing else changes.')
[void]$sb.AppendLine('    -->')
[void]$sb.AppendLine('    <Tags></Tags>')
[void]$sb.AppendLine('    <Includes>')
# keep the include the hand-written version had (known-good configuration)
[void]$sb.AppendLine('        <Include type="instance" source="DATA:BaseObjects/BaseInfantry.xml" />')
foreach ($g in $groups) { [void]$sb.AppendLine('        <Include type="instance" source="DATA:' + $g.Rel + '" />') }
[void]$sb.AppendLine('    </Includes>')
[void]$sb.AppendLine('')
foreach ($g in $groups) {
    foreach ($id in $g.Ids) {
        [void]$sb.AppendLine('    <GameObject id="' + $id + '" inheritFrom="' + $id + '">')
        [void]$sb.AppendLine('        <Behaviors>')
        [void]$sb.AppendLine('            <LUAEventList id="ModuleTag_LUAEventList" EventListName="BaseScriptFunctions" />')
        [void]$sb.AppendLine('        </Behaviors>')
        [void]$sb.AppendLine('    </GameObject>')
    }
}
[void]$sb.AppendLine('</AssetDeclaration>')

[System.IO.File]::WriteAllText($outFile, $sb.ToString(), (New-Object System.Text.UTF8Encoding($false)))
[void]$rep.Add("")
[void]$rep.Add("files used: $($groups.Count)")
[void]$rep.Add("units overridden: $($seen.Count)")
[System.IO.File]::WriteAllLines($report, $rep)
